#include <bits/stdc++.h>
using namespace std;
int main(){
    int P,R;
    int caseNum=0;
    while(cin>>P>>R && !(P==0&&R==0)){
        map<string,int> id;
        vector<vector<int>> adj;
        auto getId=[&](const string&s)->int{
            auto it=id.find(s);
            if(it!=id.end()) return it->second;
            int nid=(int)id.size();
            id[s]=nid;
            adj.push_back({});
            return nid;
        };
        for(int i=0;i<R;i++){
            string a,b; cin>>a>>b;
            int ai=getId(a), bi=getId(b);
            adj[ai].push_back(bi);
            adj[bi].push_back(ai);
        }
        int n=P;
        adj.resize(P);
        int diameter=0;
        bool disconnected=false;
        for(int s=0;s<n;s++){
            vector<int> dist(n,-1);
            queue<int>q; dist[s]=0;q.push(s);
            int reached=1;
            while(!q.empty()){
                int u=q.front();q.pop();
                for(int v: adj[u]) if(dist[v]==-1){dist[v]=dist[u]+1;q.push(v);reached++;diameter=max(diameter,dist[v]);}
            }
            if(reached<n) disconnected=true;
        }
        caseNum++;
        if(caseNum>1) cout << "\n";
        cout << "Network " << caseNum << ": " << (disconnected? string("DISCONNECTED") : to_string(diameter)) << "\n";
    }
}

